"""freshsales.py -- reproduce an icecream issue while building a Freshsales
CRM API request payload.

Simulates a fictional Freshsales "contacts" client that builds a create
payload and debugs intermediate values with ic().
"""

from icecream import ic

API_BASE = "https://example.freshsales.io/api"
API_TOKEN = "fictional-token-not-real"


def build_contact_payload(first_name, last_name, email, custom_fields=None):
    payload = {
        "contact": {
            "first_name": first_name,
            "last_name": last_name,
            "emails": [{"value": email, "is_primary": True}],
            "custom_field": custom_fields or {},
        }
    }
    ic(payload)
    return payload


def request_headers(token):
    headers = {
        "Authorization": f"Token token={token}",
        "Content-Type": "application/json",
    }
    # Debug the headers but avoid leaking the token in real usage.
    ic({k: ("<redacted>" if k == "Authorization" else v) for k, v in headers.items()})
    return headers


def main():
    ic(API_BASE)
    headers = request_headers(API_TOKEN)
    payload = build_contact_payload(
        "Ada", "Lovelace", "ada@example.com", {"cf_plan": "pro"}
    )
    body = {"url": f"{API_BASE}/contacts", "headers": headers, "json": payload}
    ic(body["url"], len(body["json"]["contact"]["emails"]))


if __name__ == "__main__":
    main()

